{
  "root_cause": "The datepicker reformats the input value to a locale-specific date string when losing focus (e.g., after pressing Escape and tabbing away) because _syncSelectedDates unconditionally updates the input with the formatted date, even when no user date selection occurred.",
  "repair_strategy": "Add a private flag _isUserSelected that is set to true only when a date is chosen via the calendar or when setSelectedDates is called programmatically. In _syncSelectedDates, update the input element's value only if the flag is true, preserving the original ISO format on initialization and focus loss.",
  "expected_accessibility_effect": "No adverse impact on keyboard navigation or screen‑reader announcements; the date field retains its announced value, preventing confusing date format changes for assistive technology users.",
  "functional_risks": [
    "External code that depends on the input value being updated to the locale format on focus loss may see unchanged values.",
    "If other components expect the formatted value after the datepicker loses focus, they will receive the ISO string instead."
  ],
  "verification_requirements": [
    "After completing the journey, the submitted departure date must equal '2026-10-22'.",
    "On page load, the departure input's value must be '2026-10-22'.",
    "Choosing a date via the calendar updates the input with the locale‑formatted date (e.g., '10/22/2026' for en‑US).",
    "Calling setSelectedDates with a date updates the input with the locale‑formatted date.",
    "Pressing Escape and then tabbing away from the date field leaves the input value unchanged."
  ],
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  private _isUserSelected: boolean = false;"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected _handleDateClick(self: Calendar, event: MouseEvent): void {
    const selectedDates = [...self.context.selectedDates]
    this._syncSelectedDates(selectedDates)

    EventHandler.trigger(this._element, EVENT_CHANGE, {
      dates: selectedDates,
      event
    })

    this._maybeHideAfterSelection(selectedDates)
  }",
      "after": "  protected _handleDateClick(self: Calendar, event: MouseEvent): void {
    this._isUserSelected = true
    const selectedDates = [...self.context.selectedDates]
    this._syncSelectedDates(selectedDates)

    EventHandler.trigger(this._element, EVENT_CHANGE, {
      dates: selectedDates,
      event
    })

    this._maybeHideAfterSelection(selectedDates)
    this._isUserSelected = false
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  setSelectedDates(dates: DatesArr): void {
    if (this._calendar) {
      this._calendar.set({ selectedDates: dates })
      this._syncSelectedDates([...this._calendar.context.selectedDates])
    }
  }",
      "after": "  setSelectedDates(dates: DatesArr): void {
    if (this._calendar) {
      this._isUserSelected = true
      this._calendar.set({ selectedDates: dates })
      this._syncSelectedDates([...this._calendar.context.selectedDates])
      this._isUserSelected = false
    }
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected _syncSelectedDates(selectedDates: string[]): void {
    const formattedDate = this._formatDateForInput(selectedDates)
    if (this._isInput) {
      this._element.value = formattedDate
    }

    if (this._boundInput) {
      this._boundInput.value = selectedDates.join(',')
    }

    if (this._displayElement) {
      this._displayElement.textContent = formattedDate
    }
  }",
      "after": "  protected _syncSelectedDates(selectedDates: string[]): void {
    const formattedDate = this._formatDateForInput(selectedDates)
    if (this._isInput) {
      if (this._isUserSelected) {
        this._element.value = formattedDate
      }
    }

    if (this._boundInput) {
      this._boundInput.value = selectedDates.join(',')
    }

    if (this._displayElement) {
      this._displayElement.textContent = formattedDate
    }
  }"
    }
  ]
}
